// Pretty-print and finalize the sitemap files generated by @astrojs/sitemap.
// - Indents the XML so it is human-readable
// - Adds a <lastmod> to the sitemap index entry pointing at sitemap-0.xml
// - Ensures consistent line endings (LF)

import { readFile, writeFile, readdir, stat } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const distFsPath = join(__dirname, '..', 'dist');

// Minimal, dependency-free XML pretty-printer that operates on the output
// produced by @astrojs/sitemap (well-formed, single-line XML).
function prettyPrintXml(xml) {
  // Insert a newline after the XML declaration.
  xml = xml.replace(/(<\?xml[^?]*\?>)/, '$1\n');

  // Normalize: strip whitespace between tags so we can re-indent cleanly.
  const normalized = xml.replace(/>\s+</g, '><').trim();

  const tokens = normalized.split(/(<[^>]+>)/g).filter((t) => t && t !== '');

  let indent = 0;
  const pad = (n) => '  '.repeat(Math.max(n, 0));
  const lines = [];

  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];

    if (token.startsWith('<?')) {
      lines.push(token);
      continue;
    }
    if (token.startsWith('<!--')) {
      lines.push(pad(indent) + token);
      continue;
    }
    if (token.startsWith('</')) {
      indent -= 1;
      lines.push(pad(indent) + token);
      continue;
    }
    if (token.startsWith('<') && token.endsWith('/>')) {
      // Self-closing tag.
      lines.push(pad(indent) + token);
      continue;
    }
    if (token.startsWith('<')) {
      // Opening tag — check whether next is a text node followed by the matching closing tag.
      const tagName = token.match(/^<([\w:]+)/)?.[1];
      const next = tokens[i + 1];
      const after = tokens[i + 2];
      if (
        tagName &&
        next &&
        !next.startsWith('<') &&
        after === `</${tagName}>`
      ) {
        // Keep <tag>text</tag> on one line.
        lines.push(pad(indent) + token + next + after);
        i += 2;
        continue;
      }
      lines.push(pad(indent) + token);
      indent += 1;
      continue;
    }
    // Bare text node (rare at this layer).
    lines.push(pad(indent) + token);
  }

  return lines.join('\n') + '\n';
}

async function processFile(filePath, { addLastmodToIndex = false } = {}) {
  let xml = await readFile(filePath, 'utf8');

  if (addLastmodToIndex) {
    const today = new Date().toISOString();
    // Inject <lastmod> right before each closing </sitemap> if missing.
    xml = xml.replace(
      /<sitemap><loc>([^<]+)<\/loc>(?!<lastmod>)/g,
      `<sitemap><loc>$1</loc><lastmod>${today}</lastmod>`
    );
  }

  const formatted = prettyPrintXml(xml);
  await writeFile(filePath, formatted, 'utf8');
  console.log(`  formatted ${filePath.split(/[\\/]/).pop()}`);
}

async function main() {
  let entries;
  try {
    entries = await readdir(distFsPath);
  } catch (err) {
    console.error('format-sitemaps: dist/ not found — did you run `astro build` first?');
    process.exit(1);
  }

  const sitemapFiles = entries.filter((name) => /^sitemap.*\.xml$/.test(name));
  if (sitemapFiles.length === 0) {
    console.warn('format-sitemaps: no sitemap files found in dist/');
    return;
  }

  console.log('format-sitemaps:');
  for (const name of sitemapFiles) {
    const filePath = join(distFsPath, name);
    const s = await stat(filePath);
    if (!s.isFile()) continue;
    await processFile(filePath, { addLastmodToIndex: name === 'sitemap-index.xml' });
  }
}

main().catch((err) => {
  console.error('format-sitemaps failed:', err);
  process.exit(1);
});
